export async function execute(args = {}) {
  const seen = new Set()
  const rows = []
  for (const r of args.rows || []) { if (seen.has(r.id)) continue; seen.add(r.id); rows.push(r) }
  return { rows, removed: (args.rows || []).length - rows.length }
}

import test from 'node:test'
import assert from 'node:assert'
import { execute } from '../lib/impl.js'
test('dedupe', async () => {
  const r = await execute({ rows: [{ id: 1 }, { id: 1 }, { id: 2 }] })
  assert.equal(r.rows.length, 2); assert.equal(r.removed, 1)
})
